/* V-19 visual design-system baseline.
   Raw reusable values live in ./tokens/index.css. Rules below must use var(...).
   Media-query breakpoints are the only CSS limitation exception. */

/* One outline weight keeps Lucide icons coherent across agent, admin, drawers, and auth. */
#root .lucide {
  stroke-width: var(--v19-icon-stroke-width);
}

/* Keep the operational canvas clean while preserving wheel, touch, and keyboard scrolling. */
:where(html, body, #root, #root *) {
  -ms-overflow-style: none;
  scrollbar-width: none;
}

:where(html, body, #root, #root *)::-webkit-scrollbar {
  display: none;
  width: var(--v19b-size-0);
  height: var(--v19b-size-0);
}

/* App bootstrap and fail-closed states keep one calm, branded shell while
   preserving the existing auth, Supabase, retry, and lazy-loading contracts. */
.v19-app-runtime-state {
  display: grid;
  width: var(--v19b-size-full);
  min-height: var(--v19b-viewport-height);
  place-items: center;
  padding: var(--v19b-size-24);
  color: var(--v19b-color-text-strong);
  background: var(--v19b-color-app);
  font-family: var(--v19-font-family);
}

.v19-app-runtime-card {
  display: grid;
  width: var(--v19b-size-full);
  max-width: var(--v19b-size-420);
  min-height: var(--v19b-size-320);
  align-content: start;
  padding: var(--v19b-size-32);
  border: var(--v19b-size-1) solid var(--v19b-color-border-strong);
  border-radius: var(--v19b-radius-panel);
  background: var(--v19b-color-panel);
  box-shadow: var(--v19b-shadow-panel);
}

.v19-app-runtime-brand {
  display: flex;
  min-width: var(--v19b-size-0);
  align-items: center;
  gap: var(--v19b-size-10);
  color: var(--v19b-color-text-muted);
  font-size: var(--v19b-size-11);
  font-weight: var(--v19b-weight-control);
  letter-spacing: var(--v19b-tracking-wide);
  text-transform: uppercase;
}

.v19-app-runtime-brand-mark {
  display: inline-grid;
  width: var(--v19b-size-32);
  height: var(--v19b-size-32);
  min-width: var(--v19b-size-32);
  place-items: center;
  border: var(--v19b-size-1) solid var(--v19b-color-primary-soft-30);
  border-radius: var(--v19b-radius-control);
  color: var(--v19b-color-primary-text);
  background: var(--v19b-color-app);
  font-size: var(--v19b-size-14);
  font-weight: var(--v19b-weight-title);
}

.v19-app-runtime-icon {
  display: inline-grid;
  width: var(--v19b-size-56);
  height: var(--v19b-size-56);
  place-items: center;
  margin-top: var(--v19b-size-32);
  border: var(--v19b-size-1) solid var(--v19b-color-primary-soft-30);
  border-radius: var(--v19b-radius-row);
  color: var(--v19b-color-primary-text);
  background: var(--v19b-color-primary-soft-10);
}

.v19-app-runtime-icon svg {
  width: var(--v19b-size-24);
  height: var(--v19b-size-24);
}

.v19-app-runtime-state.is-loading .v19-app-runtime-icon,
.v19-app-runtime-state.is-loading .v19-app-runtime-progress > span {
  animation: v19-app-runtime-pulse var(--v19b-motion-loop-fast)
    var(--v19b-ease-standard) infinite alternate;
}

.v19-app-runtime-eyebrow,
.v19-app-runtime-card h1,
.v19-app-runtime-copy,
.v19-app-runtime-detail {
  margin: var(--v19b-size-0);
}

.v19-app-runtime-eyebrow {
  margin-top: var(--v19b-size-20);
  color: var(--v19b-color-text-muted);
  font-size: var(--v19b-size-11);
  font-weight: var(--v19b-weight-control);
  letter-spacing: var(--v19b-tracking-wide);
  text-transform: uppercase;
}

.v19-app-runtime-card h1 {
  margin-top: var(--v19b-size-8);
  color: var(--v19b-color-text-strong);
  font-size: var(--v19b-size-24);
  font-weight: var(--v19b-weight-title);
  line-height: var(--v19b-line-height-title);
}

.v19-app-runtime-copy {
  margin-top: var(--v19b-size-12);
  color: var(--v19b-color-text-muted);
  font-size: var(--v19b-size-14);
  line-height: var(--v19b-line-height-copy);
}

.v19-app-runtime-detail {
  margin-top: var(--v19b-size-16);
  padding-top: var(--v19b-size-16);
  border-top: var(--v19b-size-1) solid var(--v19b-color-border);
  color: var(--v19b-color-text-faint);
  font-family: var(--v19b-font-mono);
  font-size: var(--v19b-size-11);
  line-height: var(--v19b-line-height-copy);
  overflow-wrap: anywhere;
}

.v19-app-runtime-progress {
  display: flex;
  min-height: var(--v19b-size-40);
  align-items: center;
  gap: var(--v19b-size-8);
  margin-top: var(--v19b-size-24);
  padding-inline: var(--v19b-size-12);
  border: var(--v19b-size-1) solid var(--v19b-color-border-strong);
  border-radius: var(--v19b-radius-control);
  color: var(--v19b-color-text-muted);
  background: var(--v19b-color-control);
}

.v19-app-runtime-progress > span {
  width: var(--v19b-size-8);
  height: var(--v19b-size-8);
  min-width: var(--v19b-size-8);
  border-radius: var(--v19b-radius-pill);
  background: var(--v19b-color-primary-text);
}

.v19-app-runtime-progress strong {
  font-size: var(--v19b-size-12);
  font-weight: var(--v19b-weight-control);
}

.v19-app-runtime-card button {
  display: inline-flex;
  width: var(--v19b-size-full);
  min-height: var(--v19b-size-40);
  align-items: center;
  justify-content: center;
  gap: var(--v19b-size-8);
  margin-top: var(--v19b-size-24);
  padding-inline: var(--v19b-size-16);
  border: var(--v19b-size-1) solid var(--v19b-color-primary-deep-border);
  border-radius: var(--v19b-radius-control);
  color: var(--v19b-color-text-strong);
  background: var(--v19b-color-primary);
  font: inherit;
  font-size: var(--v19b-size-12);
  font-weight: var(--v19b-weight-control);
  cursor: pointer;
  touch-action: manipulation;
  transition:
    background-color var(--v19b-motion-fast) var(--v19b-ease-standard),
    border-color var(--v19b-motion-fast) var(--v19b-ease-standard),
    transform var(--v19b-motion-fast) var(--v19b-ease-standard);
}

.v19-app-runtime-card button svg {
  width: var(--v19b-size-18);
  height: var(--v19b-size-18);
}

.v19-app-runtime-card button:hover {
  background: var(--v19b-color-primary-hover);
}

.v19-app-runtime-card button:active {
  transform: var(--v19b-transform-press);
}

.v19-app-runtime-card button:focus-visible {
  outline: var(--v19b-size-2) solid var(--v19b-color-focus);
  outline-offset: var(--v19b-size-2);
}

.v19-app-runtime-state.is-error .v19-app-runtime-card,
.v19-app-runtime-state.is-error .v19-app-runtime-icon {
  border-color: var(--v19b-admin-red-border);
}

.v19-app-runtime-state.is-error .v19-app-runtime-icon {
  color: var(--v19b-admin-red);
  background: var(--v19b-admin-red-soft);
}

.v19-app-runtime-state.is-blocked .v19-app-runtime-card,
.v19-app-runtime-state.is-blocked .v19-app-runtime-icon {
  border-color: var(--v19b-admin-orange-border);
}

.v19-app-runtime-state.is-blocked .v19-app-runtime-icon {
  color: var(--v19b-admin-orange);
  background: var(--v19b-admin-orange-soft);
}

@keyframes v19-app-runtime-pulse {
  from {
    opacity: var(--v19b-opacity-full);
  }

  to {
    opacity: var(--v19b-opacity-disabled);
  }
}

@media (max-width: 767px) {
  .v19-app-runtime-state {
    padding: var(--v19b-size-16);
  }

  .v19-app-runtime-card {
    min-height: var(--v19b-size-280);
    padding: var(--v19b-size-24);
  }

  .v19-app-runtime-icon {
    margin-top: var(--v19b-size-24);
  }
}

@media (prefers-reduced-motion: reduce) {
  .v19-app-runtime-state.is-loading .v19-app-runtime-icon,
  .v19-app-runtime-state.is-loading .v19-app-runtime-progress > span {
    animation: none;
  }
}

/* Agent sidebar: profile and selected-navigation accents stay token-driven. */
.v19-agent-sidebar-nav-item.is-active {
  border-color: var(--vf-accent-border) !important;
  background: var(--vf-accent-soft) !important;
  box-shadow: inset var(--v19b-size-3) var(--v19b-size-0) var(--v19b-size-0)
    var(--vf-info) !important;
}

/* OCR prefill: extracted values are distinct from source-file metadata. */
.v19-prefill-preview-value,
.v19-prefill-preview-confidence {
  color: var(--v19b-color-primary-text);
}

/* The prefill completion callout uses the operational warning treatment. */
.v19-prefill-ready-callout {
  border-color: var(--vf-warning-border);
  background: var(--vf-warning-soft);
}

.v19-prefill-ready-callout-icon,
.v19-prefill-ready-callout-title {
  color: var(--vf-warning);
}

.v19-prefill-ready-callout-copy {
  color: var(--v19b-color-text-80);
}

/* Admin review drawer: use the same compact operational rhythm as review/export. */
[data-admin-review-drawer-surface="workspace"] .admin-review-overview-tab,
[data-admin-review-drawer-surface="workspace"] .admin-review-applicants-tab,
[data-admin-review-drawer-surface="workspace"] .admin-review-history-tab,
[data-admin-review-drawer-surface="workspace"] .admin-review-files-tab,
[data-admin-review-drawer-surface="workspace"] .admin-review-issues-list {
  display: grid;
  min-width: var(--v19b-size-0);
  gap: var(--v19b-size-12);
}

[data-admin-review-drawer-surface="workspace"] .admin-review-overview-hero {
  display: grid;
  grid-template-columns: minmax(var(--v19b-size-0), var(--v19b-grid-fr)) auto;
  align-items: start;
  gap: var(--v19b-size-16);
  border: var(--v19b-size-1) solid var(--v19b-color-border-strong);
  border-radius: var(--v19b-radius-panel);
  background: var(--v19b-color-panel);
  padding: var(--v19b-size-18);
}

[data-admin-review-drawer-surface="workspace"] .admin-review-overview-hero > div,
[data-admin-review-drawer-surface="workspace"]
  .admin-review-overview-detail-grid
  > div {
  display: grid;
  min-width: var(--v19b-size-0);
  gap: var(--v19b-size-6);
}

[data-admin-review-drawer-surface="workspace"] .admin-review-overview-hero span,
[data-admin-review-drawer-surface="workspace"] .admin-review-overview-detail-grid span {
  color: var(--v19b-color-text-muted);
  font-size: var(--v19b-size-11);
  font-weight: var(--v19b-weight-control);
  line-height: var(--v19b-line-height-control);
  text-transform: uppercase;
}

[data-admin-review-drawer-surface="workspace"] .admin-review-overview-hero h3 {
  margin: var(--v19b-size-0);
  overflow: hidden;
  color: var(--v19b-color-text-strong);
  font-size: var(--v19b-size-24);
  font-weight: var(--v19b-weight-title);
  line-height: var(--v19b-line-height-title);
  text-overflow: ellipsis;
  white-space: nowrap;
}

[data-admin-review-drawer-surface="workspace"] .admin-review-overview-hero p {
  margin: var(--v19b-size-0);
  color: var(--v19b-color-text-muted);
  font-size: var(--v19b-size-12);
  line-height: var(--v19b-line-height-row);
}

[data-admin-review-drawer-surface="workspace"] .admin-review-overview-hero > strong {
  display: inline-flex;
  min-height: var(--v19b-size-36);
  align-items: center;
  justify-content: center;
  border: var(--v19b-size-1) solid var(--v19b-color-primary-deep-border);
  border-radius: var(--v19b-radius-control);
  background: var(--v19b-color-app);
  color: var(--v19b-color-text-strong);
  font-size: var(--v19b-size-12);
  font-weight: var(--v19b-weight-control);
  padding-inline: var(--v19b-size-12);
  white-space: nowrap;
}

[data-admin-review-drawer-surface="workspace"] .admin-review-overview-metrics {
  display: grid;
  grid-template-columns: repeat(4, minmax(var(--v19b-size-0), var(--v19b-grid-fr)));
  gap: var(--v19b-size-10);
}

[data-admin-review-drawer-surface="workspace"] .admin-review-overview-metrics article,
[data-admin-review-drawer-surface="workspace"] .admin-review-overview-detail-grid > div,
[data-admin-review-drawer-surface="workspace"] .admin-review-applicants-tab article,
[data-admin-review-drawer-surface="workspace"] .admin-review-file-row,
[data-admin-review-drawer-surface="workspace"] .admin-review-issue-card,
[data-admin-review-drawer-surface="workspace"] .admin-review-history-tab article {
  min-width: var(--v19b-size-0);
  border: var(--v19b-size-1) solid var(--v19b-color-border-strong);
  border-radius: var(--v19b-radius-row);
  background: var(--v19b-color-panel);
}

[data-admin-review-drawer-surface="workspace"] .admin-review-overview-metrics article {
  display: grid;
  gap: var(--v19b-size-6);
  padding: var(--v19b-size-14);
}

[data-admin-review-drawer-surface="workspace"] .admin-review-overview-metrics span {
  color: var(--v19b-color-text-muted);
  font-size: var(--v19b-size-11);
  font-weight: var(--v19b-weight-control);
  text-transform: uppercase;
}

[data-admin-review-drawer-surface="workspace"] .admin-review-overview-metrics strong {
  color: var(--v19b-color-text-strong);
  font-size: var(--v19b-size-22);
  font-weight: var(--v19b-weight-title);
  line-height: var(--v19b-line-height-title);
}

[data-admin-review-drawer-surface="workspace"]
  .admin-review-overview-metrics
  article.is-warning,
[data-admin-review-drawer-surface="workspace"] .admin-review-issue-card {
  border-color: var(--v19b-admin-drawer-orange-border);
}

[data-admin-review-drawer-surface="workspace"] .admin-review-overview-detail-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(var(--v19b-size-0), var(--v19b-grid-fr)));
  gap: var(--v19b-size-10);
}

[data-admin-review-drawer-surface="workspace"]
  .admin-review-overview-detail-grid
  > div {
  padding: var(--v19b-size-14);
}

[data-admin-review-drawer-surface="workspace"]
  .admin-review-overview-detail-grid
  strong {
  overflow: hidden;
  color: var(--v19b-color-text-strong);
  font-size: var(--v19b-size-14);
  font-weight: var(--v19b-weight-control);
  text-overflow: ellipsis;
  white-space: nowrap;
}

[data-admin-review-drawer-surface="workspace"] .admin-review-applicant-strip {
  display: grid !important;
  grid-template-columns: minmax(var(--v19b-size-240), var(--v19b-grid-fr)) auto;
  align-items: end;
  gap: var(--v19b-size-16);
  margin-bottom: var(--v19b-size-0) !important;
}

[data-admin-review-drawer-surface="workspace"] .admin-review-applicant-select {
  display: grid;
  gap: var(--v19b-size-6);
  min-width: var(--v19b-size-0);
}

[data-admin-review-drawer-surface="workspace"] .admin-review-applicant-select > span {
  color: var(--v19b-color-text-muted);
  font-size: var(--v19b-size-11);
  font-weight: var(--v19b-weight-control);
  text-transform: uppercase;
}

[data-admin-review-drawer-surface="workspace"] .admin-review-applicant-select select {
  width: var(--v19b-size-full);
  min-width: var(--v19b-size-0);
  min-height: var(--v19b-size-40);
  border: var(--v19b-size-1) solid var(--v19b-color-border-strong);
  border-radius: var(--v19b-radius-control);
  background: var(--v19b-color-control);
  color: var(--v19b-color-text-strong);
  font-size: var(--v19b-size-13);
  padding-inline: var(--v19b-size-12);
}

[data-admin-review-drawer-surface="workspace"] .admin-review-applicant-stats {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: flex-end;
  gap: var(--v19b-size-16);
  color: var(--v19b-color-text-muted);
  font-size: var(--v19b-size-12);
  font-weight: var(--v19b-weight-control);
}

[data-admin-review-drawer-surface="workspace"] .admin-review-applicant-stats span {
  display: inline-flex;
  align-items: center;
  gap: var(--v19b-size-6);
}

[data-admin-review-drawer-surface="workspace"] .admin-review-applicant-stats .is-ok {
  color: var(--v19b-admin-drawer-green-text);
}

[data-admin-review-drawer-surface="workspace"]
  .admin-review-applicant-stats
  .is-warning {
  color: var(--v19b-admin-drawer-orange-text);
}

[data-admin-review-drawer-surface="workspace"] .admin-review-applicants-tab {
  grid-template-columns: repeat(
    auto-fit,
    minmax(var(--v19b-size-240), var(--v19b-grid-fr))
  );
}

[data-admin-review-drawer-surface="workspace"] .admin-review-applicants-tab article {
  display: grid;
  gap: var(--v19b-size-14);
  padding: var(--v19b-size-16);
}

[data-admin-review-drawer-surface="workspace"]
  .admin-review-applicants-tab
  article.is-selected {
  border-color: var(--v19b-color-primary-deep-border);
  box-shadow: var(--v19b-shadow-primary-soft);
}

[data-admin-review-drawer-surface="workspace"] .admin-review-applicants-tab header {
  display: grid;
  grid-template-columns:
    var(--v19b-size-32) minmax(var(--v19b-size-0), var(--v19b-grid-fr))
    auto;
  align-items: center;
  gap: var(--v19b-size-10);
}

[data-admin-review-drawer-surface="workspace"]
  .admin-review-applicants-tab
  header
  > span {
  display: grid;
  width: var(--v19b-size-32);
  height: var(--v19b-size-32);
  place-items: center;
  border-radius: var(--v19b-radius-pill);
  background: var(--v19b-color-control);
  color: var(--v19b-color-text-muted);
  font-size: var(--v19b-size-12);
}

[data-admin-review-drawer-surface="workspace"] .admin-review-applicants-tab header div,
[data-admin-review-drawer-surface="workspace"] .admin-review-history-tab article div {
  display: grid;
  min-width: var(--v19b-size-0);
  gap: var(--v19b-size-4);
}

[data-admin-review-drawer-surface="workspace"]
  .admin-review-applicants-tab
  :is(strong, dd),
[data-admin-review-drawer-surface="workspace"] .admin-review-history-tab strong {
  overflow: hidden;
  color: var(--v19b-color-text-strong);
  font-size: var(--v19b-size-14);
  font-weight: var(--v19b-weight-title);
  text-overflow: ellipsis;
  white-space: nowrap;
}

[data-admin-review-drawer-surface="workspace"] .admin-review-applicants-tab small,
[data-admin-review-drawer-surface="workspace"] .admin-review-history-tab p {
  margin: var(--v19b-size-0);
  color: var(--v19b-color-text-muted);
  font-size: var(--v19b-size-12);
}

[data-admin-review-drawer-surface="workspace"] .admin-review-applicants-tab em {
  border-radius: var(--v19b-radius-pill);
  background: var(--v19b-admin-drawer-orange-bg);
  color: var(--v19b-admin-drawer-orange-text);
  font-size: var(--v19b-size-11);
  font-style: normal;
  padding: var(--v19b-size-4) var(--v19b-size-8);
}

[data-admin-review-drawer-surface="workspace"] .admin-review-applicants-tab dl {
  display: grid;
  grid-template-columns: repeat(3, minmax(var(--v19b-size-0), var(--v19b-grid-fr)));
  gap: var(--v19b-size-8);
  margin: var(--v19b-size-0);
}

[data-admin-review-drawer-surface="workspace"] .admin-review-applicants-tab dl div {
  display: grid;
  gap: var(--v19b-size-4);
  min-width: var(--v19b-size-0);
}

[data-admin-review-drawer-surface="workspace"] .admin-review-applicants-tab dt {
  color: var(--v19b-color-text-muted);
  font-size: var(--v19b-size-11);
  font-weight: var(--v19b-weight-control);
  text-transform: uppercase;
}

/* Review drawer: applicant summaries should scan as one compact identity row
   followed by three distinct metrics, not as a multiline metadata block. */
[data-admin-review-drawer-surface="workspace"]
  .admin-review-applicants-tab
  header
  > strong {
  min-width: var(--v19b-size-0);
  overflow: hidden;
  color: var(--v19b-color-text-strong);
  font-size: var(--v19b-size-14);
  font-weight: var(--v19b-weight-title);
  text-overflow: ellipsis;
  white-space: nowrap;
}

[data-admin-review-drawer-surface="workspace"]
  .admin-review-applicants-tab
  .admin-review-applicant-metric {
  min-width: var(--v19b-size-0);
  padding: var(--v19b-size-10);
  border: var(--v19b-size-1) solid var(--v19b-color-border-strong);
  border-radius: var(--v19b-radius-control);
  background: var(--v19b-color-control);
}

[data-admin-review-drawer-surface="workspace"]
  .admin-review-questionnaire
  .admin-review-field-section {
  margin-bottom: var(--v19b-size-12);
  border: var(--v19b-size-1) solid var(--v19b-color-border-strong);
