  font-size: var(--v19b-size-11);
  font-weight: var(--v19b-weight-control);
  letter-spacing: var(--v19b-size-0);
  text-transform: uppercase;
}

.v19-rail-card h3,
.v17-rail-card h2,
.v17-rail-card h3 {
  color: var(--v19b-color-text);
  font-size: var(--v19b-size-14-5);
  font-weight: var(--v19b-weight-title);
  line-height: var(--v19b-line-height-row);
}

.v19-rail-statusline,
.v19-rail-next-head,
.v17-export-summary,
.v17-export-check,
.v17-export-actions-card {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--v19b-size-10);
}

.v19-rail-statusline strong {
  color: var(--v19b-color-text-muted);
  font-size: var(--v19b-size-12);
  font-weight: var(--v19b-weight-control);
}

.v19-rail-quick-card {
  overflow: hidden;
  background:
    linear-gradient(135deg, var(--v19b-color-focus-soft), var(--v19b-color-panel)),
    var(--v19b-row-background);
}

.ops-shell:is(.surface-agent-submissions, .surface-agent-actions)
  .v19-submissions-context
  .v19-rail-quick-card {
  border-color: var(--v19b-color-border-selected) !important;
  background:
    linear-gradient(135deg, var(--v19b-color-focus-soft), var(--v19b-color-panel)),
    var(--v19b-row-background) !important;
  box-shadow: var(--v19b-shadow-card) !important;
}

.v19-rail-quick-links {
  display: grid;
  gap: var(--v19b-size-8);
}

.v19-rail-quick-links .mp-button {
  justify-content: flex-start;
  min-height: var(--v19b-size-44);
  border-color: var(--v19b-color-border-selected);
  background:
    linear-gradient(90deg, var(--v19b-color-control-hover), var(--v19b-color-control)),
    var(--v19b-color-control);
  box-shadow: var(--v19b-shadow-row-inner);
}

.ops-shell:is(.surface-agent-submissions, .surface-agent-actions)
  .v19-submissions-context
  .v19-rail-quick-links
  .mp-button {
  border-color: var(--v19b-color-border-selected) !important;
  background:
    linear-gradient(90deg, var(--v19b-color-control-hover), var(--v19b-color-control)),
    var(--v19b-color-control) !important;
  color: var(--v19b-color-text) !important;
}

.v19-rail-quick-links .mp-button:not(:disabled):hover {
  border-color: var(--v19b-color-focus);
  background:
    linear-gradient(
      90deg,
      var(--v19b-color-focus-soft),
      var(--v19b-color-control-hover)
    ),
    var(--v19b-color-control-hover);
  transform: var(--v19b-transform-raise);
}

/* Drawer header primitive */

.v19-figma-drawer-header {
  display: grid;
  gap: var(--v19b-size-14);
  padding: var(--v19b-size-20) var(--v19b-size-24) var(--v19b-size-0);
  border-bottom: var(--v19b-size-1) solid var(--v19b-color-border);
  background: var(--v19b-color-page);
}

.v19-figma-drawer-title-row {
  display: grid;
  min-width: var(--v19b-size-0);
  margin: var(--v19b-size-0);
  padding: var(--v19b-size-0);
}

.v19-figma-drawer-title-block {
  display: grid;
  min-width: var(--v19b-size-0);
  gap: var(--v19b-size-8);
}

.v19-figma-drawer-meta {
  display: grid;
  grid-template-columns:
    max-content max-content minmax(var(--v19b-size-0), var(--v19b-grid-fr))
    max-content;
  align-items: center;
  gap: var(--v19b-size-6);
  min-width: var(--v19b-size-0);
  color: var(--v19b-color-text-muted);
  font-family: var(--v19b-font-family);
  font-size: var(--v19b-size-11);
  font-weight: var(--v19b-weight-control);
  line-height: var(--v19b-line-height-control);
}

.v19-figma-drawer-meta > span:not(.v19-figma-drawer-header-status) {
  min-width: var(--v19b-size-0);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.v19-figma-drawer-meta > span:first-child {
  font-family: var(--v19b-font-mono);
  letter-spacing: var(--v19b-letter-spacing-wide);
  text-transform: uppercase;
}

.v19-figma-drawer-header-status {
  justify-self: end;
  min-width: var(--v19b-size-0);
  min-height: var(--v19b-size-30);
  padding: var(--v19b-size-6) var(--v19b-size-14);
  border: var(--v19b-size-1) solid var(--v19b-color-border-strong);
  border-radius: var(--v19b-radius-pill);
  color: var(--v19b-color-text);
  background: var(--v19b-color-control);
  font-size: var(--v19b-size-13);
  font-weight: var(--v19b-weight-control);
  line-height: var(--v19b-line-height-control);
  text-transform: lowercase;
}

.v19-figma-drawer-heading {
  margin: var(--v19b-size-0);
  color: var(--v19b-color-text);
  font-family: var(--v19b-font-family);
  font-size: var(--v19b-size-24);
  font-weight: var(--v19b-weight-title);
  line-height: var(--v19b-line-height-tight);
  letter-spacing: var(--v19b-letter-spacing-normal);
}

.v19-figma-drawer-tabs-scroll {
  width: var(--v19b-size-full);
  min-width: var(--v19b-size-0);
  overflow-x: auto;
  overscroll-behavior-x: contain;
  scrollbar-width: none;
}

.v19-figma-drawer-tabs-scroll::-webkit-scrollbar {
  display: none;
}

.v19-figma-drawer-tabs {
  display: inline-flex;
  align-items: center;
  gap: var(--v19b-size-8);
  min-width: max-content;
}

.v19-figma-drawer-tab {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--v19b-size-6);
  min-height: var(--v19b-size-44);
  padding: var(--v19b-size-0) var(--v19b-size-12);
  border: var(--v19b-size-0);
  color: var(--v19b-color-text-muted);
  background: var(--v19b-color-clear);
  font-family: var(--v19b-font-family);
  font-size: var(--v19b-size-13);
  font-weight: var(--v19b-weight-control);
  line-height: var(--v19b-line-height-control);
  white-space: nowrap;
  transition:
    color var(--v19b-motion-fast),
    background var(--v19b-motion-fast),
    transform var(--v19b-motion-fast);
}

.v19-document-package-dot {
  width: var(--v19b-size-16);
  height: var(--v19b-size-16);
  border: var(--v19b-size-1) solid var(--v19b-color-border-selected);
  border-radius: var(--v19b-radius-pill);
  background: var(--v19b-color-clear);
}

.v19-document-package-dot.is-progress {
  border-color: var(--v19b-dot-review);
  background: var(--v19b-dot-halo-review);
}

.v19-questionnaire-progress-helper {
  color: var(--v19b-dot-review) !important;
}

.v19-questionnaire-section-progress {
  height: var(--v19b-size-2) !important;
  background: var(--v19b-color-border-strong) !important;
}

.v19-questionnaire-section-progress::-webkit-progress-bar {
  background: var(--v19b-color-border-strong) !important;
}

.v19-questionnaire-section-progress::-webkit-progress-value {
  border-radius: var(--v19b-radius-pill);
}

.v19-questionnaire-section-progress::-moz-progress-bar {
  border-radius: var(--v19b-radius-pill);
}

.v19-history-composition {
  position: relative;
  display: grid;
  gap: var(--v19b-size-24);
  padding: var(--v19b-size-24);
  border: var(--v19b-size-1) solid var(--v19b-color-border-strong);
  border-radius: var(--v19b-radius-panel);
  background: var(--v19b-row-background);
}

.v19-history-composition::before {
  position: absolute;
  top: var(--v19b-size-40);
  bottom: var(--v19b-size-40);
  left: var(--v19b-size-40);
  width: var(--v19b-size-1);
  background: var(--v19b-color-border-strong);
  content: "";
}

.v19-history-item {
  position: relative;
  z-index: var(--v19b-z-base);
  display: grid;
  grid-template-columns: var(--v19b-size-32) minmax(
      var(--v19b-size-0),
      var(--v19b-grid-fr)
    );
  align-items: start;
  gap: var(--v19b-size-16);
}

.v19-history-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: var(--v19b-size-32);
  height: var(--v19b-size-32);
  border: var(--v19b-size-1) solid var(--v19b-color-border-strong);
  border-radius: var(--v19b-radius-pill);
  color: var(--v19b-color-text-muted);
  background: var(--v19b-color-control);
}

.v19-history-icon svg {
  width: var(--v19b-size-16);
  height: var(--v19b-size-16);
}

.v19-history-icon.is-warning {
  border-color: var(--v19b-dot-warning);
  color: var(--v19b-dot-warning);
  background: var(--v19b-dot-halo-warning);
}

.v19-history-icon.is-info {
  border-color: var(--v19b-dot-review);
  color: var(--v19b-dot-review);
  background: var(--v19b-dot-halo-review);
}

.v19-history-copy {
  display: grid;
  gap: var(--v19b-size-6);
  padding-top: var(--v19b-size-4);
  min-width: var(--v19b-size-0);
}

.v19-history-copy strong {
  color: var(--v19b-color-text);
  font-size: var(--v19b-size-14);
  font-weight: var(--v19b-weight-control);
  line-height: var(--v19b-line-height-row);
}

.v19-history-copy span {
  display: inline-flex;
  align-items: center;
  gap: var(--v19b-size-8);
  color: var(--v19b-color-text-muted);
  font-size: var(--v19b-size-12);
  line-height: var(--v19b-line-height-control);
}

.v19-history-copy i {
  width: var(--v19b-size-4);
  height: var(--v19b-size-4);
  border-radius: var(--v19b-radius-pill);
  background: var(--v19b-color-text-faint);
}

.v19-figma-drawer-tab:hover,
.v19-figma-drawer-tab.is-active {
  color: var(--v19b-color-text);
}

.v19-figma-drawer-tab > span:last-of-type:not(:first-child) {
  min-width: var(--v19b-size-20);
  height: var(--v19b-size-20);
  padding: var(--v19b-size-0) var(--v19b-size-6);
  border-radius: var(--v19b-size-6);
  color: var(--v19b-color-text-muted);
  background: var(--v19b-color-tag);
  font-size: var(--v19b-size-10);
  font-weight: var(--v19b-weight-title);
  line-height: var(--v19b-size-20);
  text-align: center;
}

.v19-figma-drawer-tab > span.is-warning {
  color: var(--v19b-dot-warning);
  background: var(--v19b-dot-halo-warning);
}

.v19-figma-drawer-active-tab {
  position: absolute;
  inset-inline: var(--v19b-size-0);
  bottom: var(--v19b-size-0);
  height: var(--v19b-size-2);
  border-radius: var(--v19b-radius-pill);
  background: var(--v19b-color-text);
}

/* Drawer file package primitive */

.v19-drawer-files {
  display: grid;
  gap: var(--v19b-size-16);
}

.v19-drawer-files-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--v19b-size-12);
}

.v19-drawer-files-title {
  margin: var(--v19b-size-0);
  color: var(--v19b-color-text);
  font-size: var(--v19b-size-15);
  font-weight: var(--v19b-weight-title);
  line-height: var(--v19b-line-height-row);
}

.v19-drawer-files-count,
.v19-drawer-file-section-toggle {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: var(--v19b-size-32);
  padding-inline: var(--v19b-size-10);
  border: var(--v19b-size-1) solid var(--v19b-color-border-strong);
  border-radius: var(--v19b-radius-control);
  color: var(--v19b-color-text-muted);
  background: var(--v19b-color-tag);
  font-weight: var(--v19b-weight-control);
  line-height: var(--v19b-line-height-control);
}

.v19-drawer-files-count {
  min-width: var(--v19b-size-64);
  font-size: var(--v19b-size-14);
}

.v19-drawer-file-sections {
  display: grid;
  gap: var(--v19b-size-8);
}

.v19-drawer-file-section {
  overflow: hidden;
  border: var(--v19b-size-1) solid var(--v19b-color-border-strong);
  border-radius: var(--v19b-radius-row);
  background: var(--v19b-row-background);
  box-shadow: var(--v19b-shadow-row-inner);
}

.v19-drawer-file-section-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--v19b-size-12);
  width: var(--v19b-size-full);
  padding: var(--v19b-size-14) var(--v19b-size-16);
  border: var(--v19b-size-0);
  color: inherit;
  background: var(--v19b-color-clear);
  text-align: left;
  transition:
    background var(--v19b-motion-standard),
    color var(--v19b-motion-standard);
}

.v19-drawer-file-section-head:hover {
  background: var(--v19b-color-tag);
}

.v19-drawer-file-section-copy,
.v19-drawer-file-copy {
  display: grid;
  gap: var(--v19b-size-4);
  min-width: var(--v19b-size-0);
}

.v19-drawer-file-section-title,
.v19-drawer-file-title {
  overflow: hidden;
  color: var(--v19b-color-text);
  font-size: var(--v19b-size-14);
  font-weight: var(--v19b-weight-title);
  line-height: var(--v19b-line-height-row);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.v19-drawer-file-section-meta,
.v19-drawer-file-meta {
  overflow: hidden;
  color: var(--v19b-color-text-faint);
  font-size: var(--v19b-size-12);
  line-height: var(--v19b-line-height-row);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.v19-drawer-file-section-toggle {
  font-size: var(--v19b-size-11);
}

.v19-drawer-file-list {
  display: grid;
  gap: var(--v19b-size-8);
  padding: var(--v19b-size-12);
  border-top: var(--v19b-size-1) solid var(--v19b-color-border);
}

.v19-drawer-file-item {
  display: grid;
  grid-template-columns:
    var(--v19b-size-36) minmax(var(--v19b-size-0), var(--v19b-grid-fr))
    auto;
  align-items: start;
  column-gap: var(--v19b-size-24);
  row-gap: var(--v19b-size-6);
  padding: var(--v19b-size-12);
  border: var(--v19b-size-1) solid var(--v19b-color-border);
  border-radius: var(--v19b-radius-control);
  background: var(--v19b-color-app);
}

.v19-drawer-file-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: var(--v19b-size-36);
  height: var(--v19b-size-36);
  border: var(--v19b-size-1) solid var(--v19b-color-border-strong);
  border-radius: var(--v19b-radius-control);
  color: var(--v19b-color-text-muted);
  background: var(--v19b-color-control);
}

.v19-drawer-file-icon svg {
  width: var(--v19b-size-18);
  height: var(--v19b-size-18);
}

.v19-drawer-file-action,
.v19-drawer-file-status {
  justify-self: end;
  align-self: start;
  width: auto;
  min-height: var(--v19b-size-36);
  border: var(--v19b-size-1) solid var(--v19b-color-border-strong);
  border-radius: var(--v19b-radius-control);
  color: var(--v19b-color-text);
  background: var(--v19b-color-control);
  font-size: var(--v19b-size-13);
  font-weight: var(--v19b-weight-control);
  white-space: nowrap;
}

.v19-drawer-file-action {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--v19b-size-8);
  min-width: var(--v19b-size-104);
  padding-inline: var(--v19b-size-16);
  transition:
    border-color var(--v19b-motion-standard),
    background var(--v19b-motion-standard),
    transform var(--v19b-motion-fast);
}

.v19-drawer-file-action::before {
  content: "";
  width: var(--v19b-size-6);
  height: var(--v19b-size-6);
  border-radius: var(--v19b-radius-pill);
  background: var(--v19b-dot-review);
  box-shadow: var(--v19b-dot-halo-shadow-review);
}

.v19-drawer-file-action:not(:disabled):hover {
  border-color: var(--v19b-color-border-selected);
  background: var(--v19b-color-control-hover);
  transform: var(--v19b-transform-raise);
}

.v19-drawer-file-action:disabled {
  cursor: not-allowed;
  opacity: var(--v19b-opacity-disabled);
}

.v19-drawer-file-status {
  display: inline-flex;
  align-items: center;
  gap: var(--v19b-size-8);
  min-height: var(--v19b-size-28);
  padding-inline: var(--v19b-size-10);
  border-radius: var(--v19b-radius-pill);
  color: var(--v19b-color-text-muted);
  background: var(--v19b-color-control);
}

.v19-drawer-file-status::before {
  content: "";
  width: var(--v19b-size-6);
  height: var(--v19b-size-6);
  border-radius: var(--v19b-radius-pill);
  background: var(--v19b-color-text-faint);
}

.v19-drawer-file-status.is-ready::before {
  background: var(--v19b-dot-success);
  box-shadow: var(--v19b-dot-halo-shadow-success);
}

@media (max-width: 767px) {
  .v19-drawer-file-item {
    grid-template-columns:
      var(--v19b-size-36)
      minmax(var(--v19b-size-0), var(--v19b-grid-fr))
      auto;
    column-gap: var(--v19b-size-12);
  }

  .v19-drawer-file-action,
  .v19-drawer-file-status {
    grid-column: 3;
    grid-row: 1 / span 2;
    width: auto;
    max-width: var(--v19b-size-120);
  }

  .v19-drawer-file-action {
    min-width: var(--v19b-size-96);
    padding-inline: var(--v19b-size-14);
  }

  .ops-shell.has-open-drawer .v19-figma-drawer-header {
    display: grid !important;
    gap: var(--v19b-size-12) !important;
    padding: var(--v19b-size-16) var(--v19b-size-20) var(--v19b-size-0) !important;
    border-bottom: var(--v19b-size-1) solid var(--v19b-color-border) !important;
    background: var(--v19b-color-page) !important;
  }

  .ops-shell.has-open-drawer .v19-figma-drawer-title-row {
    position: static !important;
    display: grid !important;
    width: var(--v19b-size-full) !important;
    height: auto !important;
    min-height: var(--v19b-size-0) !important;
    margin: var(--v19b-size-0) !important;
    padding: var(--v19b-size-0) !important;
  }

  .ops-shell.has-open-drawer .v19-figma-drawer-title-block {
    display: grid !important;
    gap: var(--v19b-size-8) !important;
    min-width: var(--v19b-size-0) !important;
  }

  .ops-shell.has-open-drawer .v19-figma-drawer-meta {
    display: grid !important;
    grid-template-columns:
      max-content max-content minmax(var(--v19b-size-0), var(--v19b-grid-fr))
      max-content !important;
    gap: var(--v19b-size-6) !important;
    margin: var(--v19b-size-0) !important;
    color: var(--v19b-color-text-muted) !important;
    font-size: var(--v19b-size-11) !important;
    line-height: var(--v19b-line-height-control) !important;
    text-transform: none !important;
  }

  .ops-shell.has-open-drawer .v19-figma-drawer-header-status {
    justify-self: end !important;
    min-height: var(--v19b-size-30) !important;
    padding: var(--v19b-size-6) var(--v19b-size-14) !important;
    border: var(--v19b-size-1) solid var(--v19b-color-border-strong) !important;
    border-radius: var(--v19b-radius-pill) !important;
    color: var(--v19b-color-text) !important;
    background: var(--v19b-color-control) !important;
    font-size: var(--v19b-size-13) !important;
  }

  .ops-shell.has-open-drawer .v19-figma-drawer-heading {
    margin: var(--v19b-size-0) !important;
    color: var(--v19b-color-text) !important;
    font-size: var(--v19b-size-24) !important;
    line-height: var(--v19b-line-height-tight) !important;
    letter-spacing: var(--v19b-letter-spacing-normal) !important;
