  outline: var(--v19b-size-0);
}

[data-admin-review-drawer-surface="workspace"]
  .admin-review-applicant-select-trigger:disabled {
  cursor: default;
}

[data-admin-review-drawer-surface="workspace"] .admin-review-applicant-select-value {
  min-width: var(--v19b-size-0);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

[data-admin-review-drawer-surface="workspace"]
  .admin-review-applicant-select-trigger
  > svg {
  width: var(--v19b-size-16);
  height: var(--v19b-size-16);
  color: var(--v19b-color-text-muted);
  transition: transform var(--v19b-motion-fast);
}

[data-admin-review-drawer-surface="workspace"]
  .admin-review-applicant-select-trigger
