/* Pre-upload applicant controls. Raw values live in the token layer. */
.v19-preupload-applicant-controls {
  display: flex;
  position: relative;
  min-height: 0;
  flex-direction: column;
  gap: var(--v19b-size-12);
}

.v19-preupload-family-summary {
  display: flex;
  min-height: var(--v19b-size-32);
  align-items: center;
  gap: var(--v19b-size-8);
  color: var(--v19b-color-text-50);
  font-size: var(--v19b-size-11);
}

.v19-preupload-family-summary strong {
  color: var(--v19b-color-text);
  font-weight: var(--v19b-weight-title);
}

.v19-preupload-applicant-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: var(--v19b-size-8);
}

.v19-preupload-applicant-grid[data-package-type="single"] {
  grid-template-columns: minmax(0, 1fr);
}

.v19-preupload-applicant-grid article {
  display: grid;
  min-width: 0;
  min-height: var(--v19b-size-44);
  grid-template-columns: minmax(0, 1fr) var(--v19b-size-40);
  align-items: stretch;
  overflow: hidden;
  border: var(--v19b-size-1) solid var(--v19b-color-border-strong);
  border-radius: var(--v19b-radius-control);
  background: var(--v19b-color-panel);
}

.v19-preupload-applicant-grid article.has-file {
  border-color: var(--v19b-color-border-selected);
}

.v19-preupload-applicant-grid article.is-recognized {
  border-color: var(--v19b-status-success-border);
}

.v19-preupload-applicant-grid article.is-recognized .v19-preupload-applicant-icon {
  color: var(--v19b-dot-success);
}

.v19-preupload-applicant-grid article.is-single {
  min-height: var(--v19b-size-56);
}

.v19-preupload-applicant-label,
.v19-preupload-applicant-icon {
  border: 0;
  color: var(--v19b-color-text-70);
  background: transparent;
}

.v19-preupload-applicant-label {
  display: flex;
  min-width: 0;
  align-items: center;
  gap: var(--v19b-size-6);
  padding: 0 var(--v19b-size-6) 0 var(--v19b-size-10);
  overflow: hidden;
  font-size: var(--v19b-size-11);
  font-weight: var(--v19b-weight-control);
  text-align: left;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.v19-preupload-applicant-order {
  display: grid;
  width: var(--v19b-size-20);
  height: var(--v19b-size-20);
  flex: 0 0 auto;
  place-items: center;
  border-radius: var(--v19b-radius-control);
  background: var(--v19b-color-control);
  color: var(--v19b-color-text-70);
  font-size: var(--v19b-size-10);
}

.v19-preupload-applicant-name {
  display: block;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
}

.v19-preupload-applicant-copy {
  display: flex;
  min-width: 0;
  flex: 1 1 auto;
  flex-direction: column;
  gap: var(--v19b-size-2);
  overflow: hidden;
}

.v19-preupload-applicant-details {
  display: block;
  overflow: hidden;
  color: var(--v19b-color-text-50);
  font-size: var(--v19b-size-10);
  font-weight: var(--v19b-weight-body);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.v19-preupload-applicant-icon {
  display: grid;
  width: var(--v19b-size-40);
  min-height: var(--v19b-size-44);
  place-items: center;
  border-left: var(--v19b-size-1) solid var(--v19b-color-border);
  color: var(--v19b-color-text-50);
}

.v19-preupload-applicant-icon svg {
  width: var(--v19b-size-14);
  height: var(--v19b-size-14);
}

.v19-preupload-remove-icon {
  display: none;
}

.v19-preupload-applicant-grid
  article.has-file
  .v19-preupload-applicant-icon:hover
  .v19-preupload-passport-icon {
  display: none;
}

.v19-preupload-applicant-grid
  article.has-file
  .v19-preupload-applicant-icon:hover
  .v19-preupload-remove-icon {
  display: block;
}

.v19-preupload-applicant-label:hover:not(:disabled),
.v19-preupload-applicant-icon:hover:not(:disabled) {
  color: var(--v19b-color-text);
  background: var(--v19b-color-control-hover);
}

.v19-preupload-applicant-label:focus-visible,
.v19-preupload-applicant-icon:focus-visible {
  position: relative;
  z-index: 1;
  outline: var(--v19b-size-2) solid var(--v19b-color-primary);
  outline-offset: calc(var(--v19b-size-2) * -1);
}

.v19-preupload-progress-line {
  width: min(100%, var(--v19b-size-560));
  height: var(--v19b-size-4);
  flex: none;
  align-self: center;
  overflow: hidden;
  border-radius: var(--v19b-radius-pill);
  background: var(--v19b-color-control-hover);
}

.v19-preupload-progress-stack {
  display: flex;
  width: min(100%, var(--v19b-size-560));
  flex: none;
  align-self: center;
  flex-direction: column;
  gap: var(--v19b-size-6);
}

.v19-preupload-progress-status {
  display: flex;
  align-items: center;
  justify-content: space-between;
  color: var(--v19b-color-text-50);
  font-size: var(--v19b-size-11);
}

.v19-preupload-progress-status strong {
  color: var(--v19b-color-text-70);
  font-weight: var(--v19b-weight-control);
}

.v19-preupload-upload-group {
  display: flex;
  width: 100%;
  min-height: 0;
  flex: 1 1 auto;
  flex-direction: column;
  gap: var(--v19b-size-10);
  justify-content: flex-end;
  margin-top: var(--v19b-size-12);
}

.v19-preupload-progress-line span {
  display: block;
  height: 100%;
  border-radius: inherit;
  background: var(--v19b-color-primary);
  transition: width var(--v19b-motion-target-duration) var(--v19-motion-ease-out);
}

.v19-preupload-dropzone {
  width: 100%;
  height: auto;
  max-height: 40dvh;
  flex: 1 1 auto;
  align-self: stretch;
}

@media (max-width: 1279px) {
  .v19-preupload-card {
    overflow-y: auto;
  }
}

@media (max-width: 374px) {
  .v19-preupload-family-summary {
    flex-wrap: wrap;
    gap: var(--v19b-size-4) var(--v19b-size-6);
  }

  .v19-preupload-family-summary span {
    width: 100%;
  }

  .v19-preupload-applicant-grid {
    gap: var(--v19b-size-6);
  }

  .v19-preupload-applicant-label {
    gap: var(--v19b-size-4);
    padding-right: 0;
    padding-left: var(--v19b-size-4);
    font-size: var(--v19b-size-9);
  }

  .v19-preupload-applicant-order {
    width: var(--v19b-size-16);
    height: var(--v19b-size-16);
    font-size: var(--v19b-size-8);
  }

}

@media (prefers-reduced-motion: reduce) {
  .v19-preupload-progress-line span {
    transition: none;
  }
}

