/* Shared operational summary. This is the final design-system owner for the
   identical three-card metric block used by agent and admin workspaces. */
.v19-metric-strip {
  display: grid;
  width: var(--v19b-size-full);
  min-width: var(--v19b-size-0);
  grid-template-columns: repeat(3, minmax(var(--v19b-size-0), var(--v19b-grid-fr)));
  grid-auto-rows: minmax(var(--v19b-size-88), auto);
  align-items: stretch;
  gap: var(--v19b-size-10);
}

.v19-metric-strip .v19-metric-card {
  --v19-summary-accent: var(--v19b-admin-unified-text);
  position: relative;
  display: block;
  container-type: inline-size;
  width: var(--v19b-size-full);
  min-width: var(--v19b-size-0);
  min-height: var(--v19b-size-88);
  height: var(--v19b-size-full);
  overflow: hidden;
  padding: var(--v19b-size-14);
  border: var(--v19b-size-1) solid var(--v19b-color-border-strong);
  border-radius: var(--v19b-radius-panel);
  color: inherit;
  background: transparent;
  box-shadow: var(--v19b-shadow-row-inner);
  font-family: var(--v19b-font-family);
  text-align: left;
  transition:
    border-color var(--v19b-motion-fast),
    background var(--v19b-motion-fast),
    transform var(--v19b-motion-fast);
}

