  top: var(--v19b-size-12);
  right: calc(var(--v19b-size-10) + var(--v19b-size-28) + var(--v19b-size-8));
  left: var(--v19b-size-14);
  max-width: none;
  overflow: visible;
  color: var(--v19b-admin-unified-text);
  font-size: var(--v19b-size-11);
  font-weight: var(--v19b-weight-title);
  line-height: var(--v19b-line-height-control);
  overflow-wrap: anywhere;
  text-overflow: clip;
  text-transform: uppercase;
  white-space: normal;
}

.v19-metric-strip .v19-metric-card-icon {
  position: absolute;
  top: var(--v19b-size-10);
  right: var(--v19b-size-10);
  display: inline-flex;
  width: var(--v19b-size-28);
  height: var(--v19b-size-28);
  align-items: center;
  justify-content: center;
